"""User-facing guide, separate from developer and packaging instructions."""
GUIDES = {
    'tr': [
        ('Başlarken', 'Kütüphaneyi aç düğmesi radyo, favoriler, kayıt, zamanlayıcı, beğenilen şarkılar, podcast, sesli kitap ve müzik kutusu sekmelerini açar. Uygulama NVDA kurulmadan da çalışır.'),
        ('Klavye ile kullanım', 'Tab ve Shift+Tab ile kontroller arasında, Ctrl+Tab ve Ctrl+Shift+Tab ile sekmeler arasında gezinin. Listelerde ok tuşlarını, seçili medyayı çalmak için Enter tuşunu kullanın. F1 bu yardımı açar. Komutlar ve kısayollar penceresinde bütün komutları çalıştırabilir ve genel kısayolları değiştirebilirsiniz. Boş kısayol ilgili genel tuş bileşimini kapatır. Kullanılamayan bileşimler aynı pencerede listelenir.'),
        ('Radyo ve favoriler', 'Arama alanına istasyon adını yazın, sonuç listesindeki istasyonu seçip Enter tuşuna basın. Favorilere ekle ile istasyonu saklayabilirsiniz. Kendi yayın adresinizi Özel istasyon ekle düğmesiyle girebilirsiniz. Yayınlar ve arama sonuçları internet bağlantısı gerektirir.'),
        ('Podcast ve sesli kitaplar', 'Podcast sekmesinde bir RSS adresine abone olabilir veya podcast arayabilirsiniz. Bölümü seçip Enter ile oynatın. Sesli Kitaplar sekmesinde LibriVox, Gutenberg ve GETEM kaynakları bulunur. GETEM erişimi kendi üyeliğinizi gerektirir. Bölüm konumu ve kitaplık kayıtları saklanır.'),
        ('Yerel müzik ve yer imleri', 'Müzik Kutusu sekmesinden dosya veya klasör ekleyin. Taşınan veya adı değişen yerel dosyaları yeniden seçmeniz gerekebilir. Dosya, podcast ve kitaplarda yer imi ekleyebilir; metin veya sesli not iliştirebilirsiniz. Metinli notlar, notun okunmasının bitişini bekleyebilmek için Windows sesiyle okunur.'),
        ('Başlangıç ve erişilebilirlik ayarları', 'Uygulama açıldığında son dinleneni sürdür seçeneği bu uygulamanın her açılışında son medyayı sürdürür. Ekran okuyucunun başlatılmasıyla ilgili değildir. Ekran okuyucu seçimi bildirimleri çalışan ekran okuyucuya, Windows sesi seçimi ayrı bir Windows sesine gönderir. Braille bildirimleri isteğe bağlıdır; NVDA veya JAWS ve bağlı bir braille ekranı gerekir. Braille ekranınız yoksa kutuyu işaretlemeden bırakabilirsiniz. Bildirim geçmişi son iletileri tekrar okumanızı ve kopyalamanızı sağlar.'),
        ('Kayıt, zaman kaydırma ve zamanlayıcılar', 'Kayıt sekmesinden anlık veya zamanlanmış kayıtları yönetin. Kayıt sırasında dinleme devam edebilir. Kayıt sürerken uygulamayı kapatmayı seçerseniz kayıt durdurulmadan önce onay istenir. Zaman kaydırma, ayarlardan etkinleştirilince desteklenen canlı yayınlarda geriye gitmenizi sağlar. Zamanlanmış işler için uygulama açık olmalıdır. Bilgisayar kapalıyken veya uygulama kapalıyken işler başlayamaz.'),
        ('İsteğe bağlı ses araçları', 'Çalma hızı, perde ve efektler medya türüne ve ses motoruna bağlıdır. Müzik tanıma ile bazı kayıt dönüştürmeleri FFmpeg gerektirir. Gerekli olduğunda Ayarlar bölümündeki FFmpeg yolu alanından kendi ffmpeg.exe dosyanızı seçin. Bu araç pakete dahil değildir.'),
        ('Profil yedekleme ve güncelleme', 'Profil yedekleme ve geri yükleme düğmesi ayarlarınızı, favorileri, abonelikleri, kitaplıkları, ilerleme bilgilerini ve yer imi notlarını ZIP olarak yedekler. İndirilen medya, kayıtlar ve hesap giriş bilgileri dahil değildir. Geri yükleme önce yedeği doğrular; sonraki açılışta uygulanır ve mevcut profiliniz ayrıca yedeklenir. Yeni sürüm ilk açıldığında da önceki profilin otomatik yedeği alınır. Yayın kanalı henüz açılmadıysa otomatik güncelleme ayarı gösterilmez.'),
        ('Taşınabilir kullanım ve çıkış', 'Taşınabilir ZIP dosyasını tamamen çıkarın. Ayarlar EXE yanındaki data klasöründe saklanır. Kurulu sürüm verileri kullanıcı hesabınızın AppData/Roaming/freeAudioDesktop klasöründedir. Kurulum güncellemesi bu verileri korur. Kütüphaneyi kapatmak çalmayı durdurmaz. Ana penceredeki Çıkış uygulamayı tamamen kapatır; çalma ve kayıt durur.'),
    ],
    'en': [
        ('Getting started', 'Open Library provides tabs for radio, favourites, recordings, timers, liked songs, podcasts, audio books and local music. The application runs without an NVDA installation.'),
        ('Keyboard access', 'Use Tab and Shift+Tab between controls, Ctrl+Tab and Ctrl+Shift+Tab between tabs, arrow keys in lists, and Enter to play the selected item. F1 opens this guide. Commands and Shortcuts exposes every command and lets you change global hotkeys. Leave a shortcut empty to disable it. Unavailable combinations are listed in that window.'),
        ('Radio and favourites', 'Type a station name in Search, select a result and press Enter. Add to Favourites saves a station. Add Custom Station accepts a direct audio stream address. Search and online playback require an internet connection.'),
        ('Podcasts and audio books', 'Subscribe to an RSS feed or search for a podcast, then select an episode and press Enter. Audio Books supports LibriVox, Gutenberg and GETEM. GETEM requires your own membership. Library entries and playback positions are saved.'),
        ('Local music and bookmarks', 'Add files or folders from the Jukebox tab. Select files again if you move or rename them. Bookmarks for files, episodes and book chapters may include text or recorded notes. Text notes use a Windows voice so playback can wait for the note to finish.'),
        ('Startup and accessibility settings', 'Resume last media when the application starts refers to this application, independently of screen-reader startup. Screen Reader sends notifications through a running supported screen reader; Windows Voice uses a separate Windows voice. Braille notifications are optional and require NVDA or JAWS plus a connected braille display. Leave the option unchecked if you do not use one. Notification History lets you reread and copy recent messages.'),
        ('Recording, time shift and timers', 'Manage instant and scheduled recordings on the Recording tab. Listening can continue during recording. Exiting during an active recording asks for confirmation before stopping it. Enable the time-shift buffer in Settings to rewind supported live streams. Scheduled jobs require the application to remain open; they cannot start while the computer or application is off.'),
        ('Optional audio tools', 'Speed, pitch and effects depend on the media type and audio engine. Music recognition and some recording conversions need FFmpeg. Select your ffmpeg.exe in Settings when required. FFmpeg is not bundled.'),
        ('Profile backup and updates', 'Profile Backup and Restore saves settings, favourites, subscriptions, libraries, progress and bookmark notes to a ZIP file. Downloaded media, recordings and account credentials are excluded. Restore validates the archive first and applies it on the next startup, after backing up the current profile. The first launch of a new version also backs up the previous profile. Automatic update settings are hidden until a release channel is available.'),
        ('Portable use and exit', 'Extract the complete portable ZIP. Portable preferences are stored in data next to the executable. Installed preferences are in AppData/Roaming/freeAudioDesktop under your Windows user account. Installing a new version preserves those preferences. Closing the library keeps playback running. Exit on the main window closes the application and stops playback and recording.'),
    ],
}

GUIDES['tr'].insert(2, ('Genel kısayollar', 'Temel bileşim Ctrl+Alt+Shift tuşlarıdır: R radyo, O podcast, L sesli kitap, U müzik kutusu, P oynat/duraklat, S durdur, E kayıt, I çalanın bilgisi, B yer imi. Yukarı ve aşağı ok ses düzeyini, sol ve sağ ok önceki/sonraki öğeyi değiştirir. J ve K canlı yayında geri/ileri gider. Hız için Ctrl+Alt+Shift+F7/F8, perde için Ctrl+Shift+F7/F8 kullanın. Komutlar ve kısayollar listesi tüm atamaları ve kullanılamama durumunu gösterir. Seçili komut Varsayılan kısayolu kullan düğmesiyle sıfırlanabilir. Eski özel atamalar korunur.'))
GUIDES['en'].insert(2, ('Global shortcuts', 'Use Ctrl+Alt+Shift with R for radio, O for podcasts, L for audio books, U for jukebox, P for play/pause, S for stop, E for recording, I for current information and B for a bookmark. Up/Down changes volume, Left/Right navigates items and J/K rewinds/forwards live audio. Ctrl+Alt+Shift+F7/F8 changes speed; Ctrl+Shift+F7/F8 changes pitch. Commands and Shortcuts shows every binding and its availability. Use Default Shortcut restores the selected binding. Existing custom bindings are preserved.'))

GUIDES['tr'].insert(3, ('Anlık radyo kaydı', 'Radyo veya Favoriler listesinde sağ tık, Uygulamalar tuşu ya da Shift+F10 ile menüyü açın. Dinlenen istasyonun anlık kaydını başlat o anda çalan radyoyu kaydeder. Başka bir liste öğesinin seçilmesi kayıt kaynağını değiştirmez. Ses verisi geldiğinde başladığı bildirilir. Aynı menüde Anlık kaydı durdur ile bitirin; dosyanın tam yolu bildirilir. Kayıt klasörünü aç ile dosyaya ulaşın. Dinleme durdurulsa veya başka istasyona geçilse de kayıt sürer. Her kayıt ayrı dosyaya yazılır.'))
GUIDES['en'].insert(3, ('Instant radio recording', 'In Radio or Favourites, right-click or press the Applications key or Shift+F10. Start Instant Recording of Playing Station records the radio currently playing, regardless of the selected list item. Success is announced after audio data arrives. Use Stop Instant Recording in the same menu to save; the complete file path is announced. Open Recordings Folder opens the destination. Changing or stopping playback does not interrupt the independent recording. Every recording has its own file.'))

GUIDES['tr'].insert(1, ('Çalmayı durdurma', 'Ana penceredeki Çalmayı durdur (F8) düğmesini kullanın. Başlangıçta son medya otomatik çalınıyorsa ilk odak bu düğmededir. Ana pencere ve kütüphanede F8, uygulama dışındayken Ctrl+Alt+Shift+S çalmayı durdurur. Bekleyen bağlantı da iptal edilir; bağımsız radyo kayıtları devam eder. Duraklat/sürdür düğmesi çalan medyayı duraklatır veya sürdürür.'))
GUIDES['en'].insert(1, ('Stopping playback', 'Use Stop Playback (F8) on the main window. It receives initial focus when startup resume is enabled. F8 in the main window or library, or Ctrl+Alt+Shift+S outside the application, stops playback and cancels pending connections. Independent radio recordings continue. Pause / Resume controls the current media.'))
GUIDES['tr'].append(('Uygulama içinden güncelleme', 'Güncellemeleri denetle yeni sürümü indirme seçeneklerini açar. Kurulu sürüm indir ve kur ile doğrulanmış kurulumu çalıştırır ve yeniden açılır. İndirme iptal edilebilir. Ayarlar korunur; yeni sürüm ilk açılışta profil yedeği alır. Taşınabilir sürüm ZIP indirir: uygulamayı kapatıp yeni ZIP dosyasını açarken data klasörünüzü koruyun. Paketler henüz dijital imzalı değildir; özet doğrulaması yayıncı imzası değildir.'))
GUIDES['en'].append(('In-app updates', 'Check for Updates offers download choices. Installed copies can download, verify, install and restart. Downloads can be cancelled. Settings are preserved and the new version backs up the profile on first launch. Portable copies download a ZIP: close the application and preserve your data folder when extracting it. Packages are currently unsigned; checksum verification is not a publisher signature.'))

GUIDES['tr'].insert(2, ('Durdurduktan sonra yeniden oynatma', 'Durdur veya F8 sonrasında son dinleneni yeniden açmak için ana penceredeki Oynat / duraklat / sürdür düğmesine Tab ile gelin ve Boşluk ya da Enter tuşuna basın. Çalma sırasında bu düğme duraklatır, duraklatılmış medyayı sürdürür. Kayıtlı son medya yoksa önce kütüphaneden seçim yapın. Genel kısayolların çift ve üç basış ayarları bu düğmeyi etkilemez.'))
GUIDES['en'].insert(2, ('Playing again after Stop', 'After Stop or F8, use Tab to focus Play / pause / resume on the main window and press Space or Enter to restart the last saved media. The same button pauses playing media or resumes paused media. If there is no saved media, choose an item in the library first. Global hotkey double/triple-press settings do not affect this button.'))

# Replace obsolete transport instructions while keeping the rest of the guide.
for language, titles in [('tr', {'Çalmayı durdurma', 'Durdurduktan sonra yeniden oynatma'}), ('en', {'Stopping playback', 'Playing again after Stop'})]:
    GUIDES[language] = [(title, body) for title, body in GUIDES[language] if title not in titles]
GUIDES['tr'].insert(1, ('Odağı değiştirmeden oynatma', 'Ana pencere ve kütüphanede F8 çalmayı veya bekleyen bağlantıyı durdurur. İkinci F8 son dinleneni yeniden açar. Aynı düğme Oynatmayı durdur (F8) ve Son dinleneni oynat (F8) arasında etiket değiştirir; Boşluk veya Enter ile odağı değiştirmeden kullanılır. Durdurma sürerken ikinci basış yeniden oynatmayı sıraya alır; üçüncü basış iptal eder. Tuşu basılı tutmak geçişleri tekrarlamaz. Genel Ctrl+Alt+Shift+S yalnız durdurur. Ayrı Oynat / duraklat / sürdür düğmesi duraklatılmış medyayı sürdürür. Bağımsız kayıtlar devam eder.'))
GUIDES['en'].insert(1, ('Playback without moving focus', 'F8 in the main window and library stops playback or a pending connection; a second F8 plays the last saved media. The same button changes between Stop Playback (F8) and Play Last Media (F8), keeping focus for Space or Enter. A second press during a slow stop queues playback and a third cancels that request. Holding F8 does not repeat the toggle. Ctrl+Alt+Shift+S remains stop-only. The separate Play / Pause / Resume button resumes paused media. Independent recordings continue.'))
